'use strict';
const E=Galactic,$=id=>document.getElementById(id),app=$('app'),modal=$('modal-root');
let game=E.createGame('alliance'),selection=null,target=null,hover=null,canvas,ctx,zoom=1,pan={x:0,y:0},fitScale=1,offset={x:0,y:0},mapSize={w:0,h:0},effects=[],setup={side:'alliance',mode:'conquest',difficulty:'normal'},shop={station:null,branch:'Escort',stack:1},lastTime=0,toastTimer,aiToken=0,pointer=null,readyCache=new Map(),targetCache=new Set();
let detailOpen=false;
const R=43,SQ=Math.sqrt(3),count=n=>Math.round(n).toLocaleString('en-US'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ownUnits=()=>game.units.filter(u=>u.hp>0&&u.side===game.player),selectedUnit=()=>selection?.kind==='unit'?game.units.find(u=>u.id===selection.id&&u.hp>0):null,selectedStation=()=>selection?.kind==='station'?game.stations.find(s=>s.id===selection.id):null;
const interactive=()=>!game.over&&game.phase===game.player;
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function save(){if(game.phase!==game.player)return;try{localStorage.setItem('galactic-command-hex-v2',JSON.stringify(game));}catch(e){toast('This browser could not save progress. Keep this tab open.');}}
function getSave(){try{const g=JSON.parse(localStorage.getItem('galactic-command-hex-v2'));if(g?.version===2&&g.tiles?.length===g.cols*g.rows&&g.units&&g.stations&&E.FACTIONS[g.player])return g;}catch(e){}return null;}
function focusDialog(){setTimeout(()=>modal.querySelector('button:not(:disabled),select')?.focus(),15);}
function closeModal(){modal.innerHTML='';canvas?.focus({preventScroll:true});}
function newGame(){aiToken++;game=E.createGame(setup.side,setup.difficulty,setup.mode,Date.now()>>>0);selection={kind:'unit',id:ownUnits().find(u=>u.admiral)?.id};target=null;effects=[];zoom=1;pan={x:0,y:0};closeModal();render();save();toast('Select a fleet, move on blue hexes, then target a red hex.');}
function startMenu(){const saved=getSave();modal.innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="Campaign setup"><div class="eyebrow">Legend of the Galactic Heroes · WC4-inspired tactics</div><h1>One galaxy.<br>Every hex contested.</h1><p>Build a fleet. Appoint your admirals. Break the enemy line with coordinated firepower—and take the stations that keep the war alive.</p><div class="choice-grid"><button class="faction empire ${setup.side==='empire'?'active':''}" data-faction="empire">${ART.portrait("reinhard","faction-portrait")}<span class="label gold">The golden lion</span><h3>Galactic Empire</h3><p>Reinhard, Mittermeyer, Reuenthal, and Kircheis. Decisive offensives and rapid breakthroughs.</p><span class="select-mark">${setup.side==='empire'?'✓ Command selected':'Select the Empire'}</span></button><button class="faction alliance ${setup.side==='alliance'?'active':''}" data-faction="alliance">${ART.portrait("yang","faction-portrait")}<span class="label cyan">The magician’s fleet</span><h3>Free Planets Alliance</h3><p>Yang, Attenborough, Fischer, and Schönkopf. Counterattacks, maneuver, and boarding operations.</p><span class="select-mark">${setup.side==='alliance'?'✓ Command selected':'Select the Alliance'}</span></button></div><div class="setup-row"><div><label for="mode-select">Operation</label><select class="select" id="mode-select"><option value="conquest" ${setup.mode==='conquest'?'selected':''}>Galactic conquest · 17 × 11 hexes</option><option value="iserlohn" ${setup.mode==='iserlohn'?'selected':''}>Assault on Iserlohn · 18-turn scenario</option></select></div><div><label for="difficulty-select">Difficulty</label><select class="select" id="difficulty-select"><option value="easy" ${setup.difficulty==='easy'?'selected':''}>Cadet · extra resources, weaker enemy economy</option><option value="normal" ${setup.difficulty==='normal'?'selected':''}>Admiral · equal economic rules</option><option value="hard" ${setup.difficulty==='hard'?'selected':''}>Fleet Marshal · enemy income +20%</option></select></div></div><div class="badge-row"><span class="badge">13 ship classes</span><span class="badge">8 admirals</span><span class="badge">4 research lines</span><span class="badge">1–3-stack fleets</span></div><div class="dialog-footer"><div><button class="primary" data-action="start">Launch operation</button>${saved?'<button data-action="continue">Continue saved game</button>':''}<button class="ghost" data-action="help">Field manual</button></div><small>Unofficial fan game. Alternate-history scenarios.<br>Saved in this browser. A new operation replaces your hex-campaign save.</small></div></section></div>`;focusDialog();}
function render(){document.documentElement.style.setProperty('--own',E.FACTIONS[game.player].color);const e=game.economy[game.player],inc=E.income(game,game.player),stations=game.stations.filter(s=>s.owner===game.player).length;app.innerHTML=`<header class="topbar"><div class="brand"><span class="mark" aria-hidden="true">⬡</span><div><h1>Galactic Command</h1><small>LEGEND OF THE GALACTIC HEROES</small></div></div><div class="resources"><div class="resource"><span class="label"><i class="resource-symbol">$</i> Credits</span><b>${count(e.credits)} <small>+${inc.credits}/turn</small></b></div><div class="resource"><span class="label"><i class="resource-symbol">⚙</i> Industry</span><b>${count(e.industry)} <small>+${inc.industry}/turn</small></b></div><div class="resource"><span class="label"><i class="resource-symbol">◉</i> Research</span><b>${count(e.science)} <small>+${inc.science}/turn</small></b></div><div class="resource"><span class="label">Stations</span><b>${stations} <small>/ ${game.stations.length}</small></b></div></div><nav class="top-actions" aria-label="Command menus"><button class="small" data-action="research" ${!interactive()?'disabled':''}>Research</button><button class="small" data-action="admirals" ${!interactive()?'disabled':''}>Admirals</button><button class="small ghost" data-action="archive">Units</button><button class="small ghost" data-action="help" aria-label="Field manual">?</button><button class="small ghost" data-action="menu" ${game.phase!==game.player?'disabled':''}>Menu</button></nav></header><div class="workbench"><main class="theater"><div class="theater-head"><div><span class="label" style="color:${E.FACTIONS[game.phase].color}">Turn ${String(game.turn).padStart(2,'0')} · ${E.FACTIONS[game.phase].short} phase</span><h2>${game.mode==='iserlohn'?'Assault on Iserlohn':'The galactic frontier'}</h2></div><p class="objective">${game.mode==='iserlohn'?'Capture Iserlohn by turn 18. Breach its shields, then occupy the station.':`Capture ${game.player==='alliance'?'Odin':'Heinessen'} while holding your own capital.`}</p></div><div class="map-wrap"><canvas id="map" tabindex="0" aria-label="Hex battlefield. Select your fleet using the fleet selector or N. Arrow keys move the hex cursor; Enter selects. F fires at a selected target. Drag to pan; plus and minus zoom."></canvas><div class="map-banner" id="map-banner">${game.phase!==game.player?'Enemy fleets are maneuvering…':'Select a fleet to reveal its movement and firing range.'}</div><div class="map-tools"><button data-action="zoom-out" aria-label="Zoom out">−</button><button data-action="fit">Fit</button><button data-action="zoom-in" aria-label="Zoom in">+</button></div><div class="map-legend"><span style="color:var(--gold)"><i class="legend-dot"></i>Empire</span><span style="color:var(--cyan)"><i class="legend-dot"></i>Alliance</span><span style="color:#b8a9cf"><i class="legend-dot"></i>Nebula</span><span>◇ Station</span><span>× Gravity rift</span></div></div><div class="map-caption"><span id="map-caption">Blue hex: move · Red hex: target · Select a target, then Fire</span><span>Drag to pan · Scroll to zoom · <span class="kbd">N</span> next fleet</span></div></main><aside class="side" id="side"></aside><div class="selection-dock" id="selection-dock"></div></div><footer class="footer"><div class="turn-status" id="turn-status"></div><div class="footer-actions"><button class="small" data-action="details">Fleet orders</button><button class="small" data-action="next" ${!interactive()?'disabled':''}>Next fleet <span class="kbd">N</span></button><button class="primary end" data-action="end" ${!interactive()?'disabled':''}>${game.phase===game.player?'End turn':'Enemy turn…'}</button></div></footer>`;canvas=$('map');ctx=canvas.getContext('2d');attachMap();updateSelection();}
function updateSelection(){const u=selectedUnit();readyCache=u&&u.side===game.player?E.reachable(game,u):new Map();targetCache=new Set(u&&u.side===game.player&&!u.attacked&&u.morale>-3?E.targets(game,u).map(E.key):[]);$('side').innerHTML='<button class="drawer-close small" data-action="details" aria-label="Close fleet orders">×</button>'+panel();$('side').classList.toggle('open',detailOpen);$('selection-dock').innerHTML=dockHTML();const ready=ownUnits().filter(u=>!u.attacked&&u.morale>-3).length;$('turn-status').innerHTML=game.over?'Operation concluded':`${ready} fleets ready <small>${E.FACTIONS[game.player].short} · ${game.difficulty} · autosaved</small>`;$('map-banner').textContent=game.phase!==game.player?'Enemy fleets are maneuvering…':game.over?'Operation concluded':u?.side===game.player?`${u.admiral?E.ADMIRALS[u.admiral].short+' · ':''}${E.TYPES[u.type].short} ×${u.stack}${u.morale<=-3?' · In confusion':u.attacked?' · Orders complete':''}`:selectedStation()?`${selectedStation().name} · ${selectedStation().owner===game.player?'Select Shipyard to build fleets':'Breach shields before capture'}`:'Select a fleet to reveal movement and firing range.';}
function moraleName(n){return n>=1?'High (+25%)':n===0?'Steady':n===-1?'Low (−25%)':n===-2?'Diminished (−50%)':'Confused';}
function panel(){const u=selectedUnit(),s=selectedStation();const fleetPicker=`<label class="label" for="fleet-select">Your fleets</label><select class="select unit-select" id="fleet-select"><option value="">Select a fleet…</option>${ownUnits().map(v=>`<option value="${v.id}" ${u?.id===v.id?'selected':''}>${v.admiral?E.ADMIRALS[v.admiral].short+' · ':''}${E.TYPES[v.type].short} ×${v.stack} [${v.c},${v.r}]${v.attacked?' · spent':''}</option>`).join('')}</select>`;let main='';
 if(u){const t=E.TYPES[u.type],ours=u.side===game.player,st=E.stationAt(game,u),a=E.ADMIRALS[u.admiral];main=`<section>${fleetPicker}<div class="side-title"><span class="label">${t.branch}</span><span class="chip" style="color:${E.FACTIONS[u.side].color}">${E.FACTIONS[u.side].short}</span></div>${ART.ship(u.type,"panel-ship")}<h2 class="unit-name">${a&&u.type==='flagship'?a.hull:t.name}</h2><p class="description">${a&&u.type==='flagship'?t.name+' · ':''}${t.desc}</p><div class="hp-row"><span>Hull integrity</span><span class="mono">${Math.ceil(u.hp)} / ${E.maxHP(u)}</span></div><div class="bar"><i style="width:${u.hp/E.maxHP(u)*100}%;background:${E.FACTIONS[u.side].color}"></i></div><div class="stat-grid"><div><span class="label">Attack</span><b>${Math.round(t.attack*(1+.45*(u.stack-1)))}</b></div><div><span class="label">Armor</span><b>${t.armor}</b></div><div><span class="label">Movement</span><b>${E.movement(game,u)}</b></div><div><span class="label">Range</span><b>${t.min===t.max?t.max:t.min+'–'+t.max}</b></div><div><span class="label">Stack</span><b>${u.stack}/${t.elite?1:3}</b></div><div><span class="label">Veteran</span><b>${u.xp}/5</b></div></div><div class="status-line"><span class="status ${u.moved?'spent':'ready'}">${u.moved?'Moved':'Move ready'}</span><span class="status ${u.attacked?'spent':'ready'}">${u.attacked?'Fired':'Fire ready'}</span><span class="status">${moraleName(u.morale)}</span></div>${target&&ours?targetPanel(u):''}${a?`<div class="admiral-card">${ART.portrait(u.admiral)}<b>★ ${a.name}</b><p>${a.skill} · ${a.desc}</p></div>`:''}${ours?`<div class="actions">${!a?'<button data-action="assign">Assign admiral <small>Choose officer</small></button>':''}${a?.trait==='magician'?`<button data-action="confuse" ${!interactive()||u.confusionCD>0?'disabled':''}>Confusion <small>${u.confusionCD?'Ready in '+u.confusionCD+' turns':'−2 morale · 2 hex radius'}</small></button>`:''}<button data-action="reinforce" ${!interactive()||t.elite||u.stack>=3||u.moved||u.attacked?'disabled':''}>Add a stack <small>${Math.round(t.cost*.8)} cr · ${Math.round(t.industry*.8)} ind</small></button><button data-action="repair" ${!interactive()||u.moved||u.attacked||u.hp>=E.maxHP(u)?'disabled':''}>Repair fleet <small>+35% HP · ${45+u.stack*15} cr</small></button><button data-action="wait" ${!interactive()||u.attacked?'disabled':''}>Hold position <small>Finish this fleet’s turn</small></button></div><p class="description" style="font-size:11px">Repair and stacking require a friendly station within 1 hex and consume this fleet’s turn.</p>`:''}${st?`<div class="section-divider"><span class="label">Station beneath fleet</span><div class="station-buttons"><button data-station="${st.id}">${st.name} · Tier ${st.tier}</button>${st.owner===game.player?`<button data-shop="${st.id}" ${!interactive()?'disabled':''}>Shipyard</button>`:''}</div></div>`:''}</section>`;
 }else if(s){const ours=s.owner===game.player;main=`<section>${fleetPicker}<div class="side-title"><span class="label">${s.capital?'Capital':s.fort?'Orbital fortress':'Sector hub'}</span><span class="chip" style="color:${E.FACTIONS[s.owner].color}">${E.FACTIONS[s.owner].short}</span></div>${ART.ship(s.capital?"capital":s.fort?"fortress":"station","panel-ship")}<h2 class="unit-name">${s.name}</h2><p class="description">${s.fort?'Fortress defenses protect this strategic corridor.':s.capital?'The seat of government and a major industrial center.':'Capture and hold this station to fund your fleets.'}</p><div class="hp-row"><span>Station defenses</span><span class="mono">${Math.ceil(s.shield)} / ${s.maxShield}</span></div><div class="bar"><i style="width:${s.shield/s.maxShield*100}%;background:${E.FACTIONS[s.owner].color}"></i></div><div class="stat-grid"><div><span class="label"><i class="resource-symbol">$</i> Credits</span><b>+${s.income}</b></div><div><span class="label"><i class="resource-symbol">⚙</i> Industry</span><b>+${s.industry}</b></div><div><span class="label"><i class="resource-symbol">◉</i> Research</span><b>+${s.science}</b></div></div><div class="info-strip">Shipyard tier ${s.tier} / 3<br>${s.tier===3?'All hull classes available':s.tier===2?'Escort, cruisers, and siege hulls':'Light escorts, cruisers, beam frigates'}</div>${ours?`<div class="actions"><button class="primary" data-shop="${s.id}" ${!interactive()||s.producedTurn===game.turn?'disabled':''}>${s.producedTurn===game.turn?'Production complete this turn':'Open shipyard'}<small>Build a fleet</small></button><button data-action="upgrade" ${!interactive()||s.tier>=3?'disabled':''}>Upgrade shipyard<small>${s.tier>=3?'Maximum tier':130*s.tier+' cr · '+35*s.tier+' ind'}</small></button></div><p class="description">One fleet per station per turn. New fleets act next turn. Garrisons repair 8% hull here each turn.</p>`:'<p class="description">Reduce defenses to zero and eliminate any garrison, then enter with an Escort or Battle Line unit to capture. Artillery cannot capture stations.</p>'}</section>`;
 }else{main=`<section>${fleetPicker}<div class="empty-panel"><span class="eyebrow">Command the frontier</span><h3>Position.<br>Concentrate.<br>Break through.</h3><p class="description">Select a fleet to see its movement and attack range. Select a station to build new ships.</p><div class="info-strip">Move once, then fire once per turn. A Battle Line kill can refresh both actions.</div><button data-action="next">Select a ready fleet</button></div></section>`;}
 const selectedTile=selection?.kind==='tile'?E.tile(game,selection.c,selection.r):u?E.tile(game,u.c,u.r):s?E.tile(game,s.c,s.r):null;return main+`<section class="section-divider"><span class="label">${selectedTile?'Hex '+selectedTile.c+', '+selectedTile.r:'Theater intelligence'}</span><p class="description">${selectedTile?terrainDescription(selectedTile):'Iserlohn, Vermilion, and Fezzan form three crossings through the gravity rifts.'}</p><label class="label" for="station-select">Station directory</label><select class="select unit-select" id="station-select"><option value="">Inspect station…</option>${game.stations.map(s=>`<option value="${s.id}">${s.name} · ${E.FACTIONS[s.owner].short}</option>`).join('')}</select></section><section class="section-divider dispatches"><span class="label">Command dispatches</span>${game.log.slice(0,4).map(l=>`<p class="dispatch"><b>T${l.turn}</b> ${esc(l.text)}</p>`).join('')}</section>`;}
function terrainDescription(t){return t.terrain==='nebula'?'Nebula · Movement cost 2. Fleets lose 2.5% maximum HP at the start of their turn. Yang ignores the movement penalty.':t.terrain==='asteroid'?'Asteroid field · Movement cost 2. Incoming damage reduced by 15%. Yang ignores the movement penalty.':t.terrain==='rift'?'Gravity rift · Impassable. Reach the central crossings to pass between territories.':'Deep space · Movement cost 1. No terrain defense or attrition.';}
function targetPanel(u){const pr=E.preview(game,u.id,target.c,target.r);if(!pr)return'';const d=E.unitAt(game,target),s=E.stationAt(game,target);return `<div class="target-box"><span class="label">Firing solution</span><h3>${d?E.TYPES[d.type].short:s.name}</h3><p>${s?'At '+s.name+' · ':''}${E.distance(u,target)} hexes away · ${Math.round(pr.armorPen*100)}% armor penetration</p><div class="damage-grid"><div><b>${pr.unit||pr.shield}</b><small>${pr.unit?'Estimated hull damage':'Station damage'}</small></div><div><b>${pr.counterAllowed?pr.counter:'None'}</b><small>Counter-fire</small></div></div><p>${pr.unit&&pr.shield?'Also ~'+pr.shield+' station damage. ':''}${Math.round(pr.crit*100)}% critical chance (${pr.critMult.toFixed(2)}×).${pr.splash?'<br>45% splash damage + morale loss to adjacent enemies.':''}${!pr.counterAllowed?'<br>Enemy cannot retaliate against this attack.':''}</p><button data-action="fire" ${!interactive()||u.attacked||u.morale<=-3?'disabled':''}>Fire <span class="kbd">F</span></button><button class="ghost" style="background:transparent;color:#c9b7bb;font-weight:400" data-action="cancel-target">Cancel target</button></div>`;}
function selectUnit(id,center=false){const u=game.units.find(v=>v.id===id&&v.hp>0);if(!u)return;selection={kind:'unit',id};target=null;updateSelection();if(center)centerOn(u);}
function selectStation(id,center=false){const s=game.stations.find(v=>v.id===id);if(!s)return;selection={kind:'station',id};target=null;updateSelection();if(center)centerOn(s);}
function nextFleet(){const ready=ownUnits().filter(u=>!u.attacked&&u.morale>-3);if(!ready.length){toast('All fleets have completed their orders. End the turn to continue.');return;}const i=ready.findIndex(u=>u.id===selection?.id);selectUnit(ready[(i+1)%ready.length].id,true);}
function refreshAndSave(){render();save();if(game.over)resultDialog();}
function doAction(fn){if(!interactive())return;const result=fn();if(!result?.ok){toast(result?.reason||'Order unavailable.');return;}target=null;refreshAndSave();}
function executeFire(){const u=selectedUnit();if(!u||!target||!interactive())return;const result=E.attack(game,u.id,target.c,target.r);if(!result.ok){toast(result.reason);return;}addCombatEffects(result,u.side);target=null;refreshAndSave();if(result.breakthrough)toast('Breakthrough! This fleet can move and attack again.');}
async function endTurn(force=false){if(!interactive())return;const ready=ownUnits().filter(u=>!u.attacked&&u.morale>-3).length;if(ready&&!force){modal.innerHTML=`<div class="overlay"><section class="dialog narrow" role="dialog" aria-modal="true" aria-label="End turn"><div class="eyebrow">Review orders</div><h2>${ready} fleets still have orders.</h2><p>You can end the turn now and leave them holding position, or return to issue their orders.</p><div class="dialog-footer"><button data-action="close">Return to the map</button><button class="primary" data-action="end-confirm">End turn</button></div></section></div>`;focusDialog();return;}closeModal();save();const token=++aiToken;const enemy=E.opponent(game.player);E.beginTurn(game,enemy,true);target=null;E.aiProduction(game);render();const ids=game.units.filter(u=>u.hp>0&&u.side===enemy&&!u.attacked).map(u=>u.id);for(const id of ids){if(token!==aiToken||game.over)break;const u=game.units.find(u=>u.id===id);if(!u)continue;const orders=E.aiOrder(game,id);for(const o of orders){if(o.kind==='attack')addCombatEffects(o,enemy);else effects.push({kind:'move',unitId:id,from:o.from,to:o.to,color:E.FACTIONS[enemy].color,life:.5,max:.5});}if(orders.length){updateSelection();await new Promise(resolve=>setTimeout(resolve,matchMedia('(prefers-reduced-motion: reduce)').matches?15:150));}}
 if(token!==aiToken)return;game.turn++;E.beginTurn(game,game.player,true);render();save();if(game.over)resultDialog();else toast(`Turn ${game.turn}. Income collected; fleet orders refreshed.`);}
function resultDialog(){const win=game.over.winner===game.player;modal.innerHTML=`<div class="overlay"><section class="dialog narrow" role="dialog" aria-modal="true" aria-label="Operation result"><div class="eyebrow">${win?'Operation successful':game.over.winner==='draw'?'Armistice':'Operation ended'}</div><h2>${win?'The galaxy remembers.':game.over.winner==='draw'?'A fragile peace.':'The fleet’s last order.'}</h2><p>${game.over.reason}</p><div class="result-numbers"><div><b>${game.turn}</b><small>Turns elapsed</small></div><div><b>${game.stations.filter(s=>s.owner===game.player).length}</b><small>Stations held</small></div><div><b>${ownUnits().length}</b><small>Fleets remaining</small></div></div><div class="dialog-footer"><button data-action="close">Inspect battlefield</button><button class="primary" data-action="new">New operation</button></div></section></div>`;focusDialog();}
function openShop(id,branch=shop.branch){const s=game.stations.find(s=>s.id===id);if(!s||s.owner!==game.player||!interactive())return;shop.station=id;shop.branch=branch;const free=E.recruitOptions(game,s,game.player);modal.innerHTML=`<div class="overlay"><section class="dialog wide" role="dialog" aria-modal="true" aria-label="Shipyard"><div class="dialog-head"><div><div class="eyebrow">${s.name} · Shipyard tier ${s.tier}</div><h2>Commission a fleet</h2><p><span class="resource-inline">${count(game.economy[game.player].credits)} credits · ${count(game.economy[game.player].industry)} industry</span></p></div><button class="small close" data-action="close">Close</button></div><div class="toolbar-row"><div class="tabs">${['Escort','Battle Line','Artillery'].map(b=>`<button data-branch="${b}" class="${b===branch?'active':''}">${b}</button>`).join('')}</div><div><label for="stack-select">Fleet strength &nbsp;</label><select class="select" id="stack-select">${[1,2,3].map(n=>`<option value="${n}" ${shop.stack===n?'selected':''}>${n} ${n===1?'stack':'stacks'}</option>`).join('')}</select></div></div>${s.producedTurn===game.turn?'<div class="info-strip">This shipyard has completed production for this turn.</div>':!free.length?'<div class="info-strip">No free deployment hex. Move friendly fleets away from the station.</div>':'<p class="description">One fleet per station per turn. Deployment uses the station hex, or a free adjacent hex. New fleets act next turn.</p>'}<div class="cards">${Object.entries(E.TYPES).filter(([k,t])=>t.branch===branch).map(([k,t])=>{const n=t.elite?1:shop.stack,p=E.price(k,n),can=E.canBuy(game,s,k,n);return `<article class="unit-card ${s.tier<t.tier?'locked':''}">${ART.ship(k,"catalog-ship")}<span class="unit-code">${t.code} · ×${n}</span><h3>${t.name}</h3><p>${t.desc}</p><div class="unit-spec"><span>HP ${Math.round(t.hp*(1+.7*(n-1)))}</span><span>ATK ${Math.round(t.attack*(1+.45*(n-1)))}</span><span>MOV ${t.move}</span><span>RNG ${t.min}–${t.max}</span></div><div class="cost">${p.credits} cr · ${p.industry} ind</div><button data-recruit="${k}" ${!can?'disabled':''}>${s.tier<t.tier?'Requires shipyard tier '+t.tier:t.elite?'Build elite battery · 1 stack':'Commission fleet'}</button></article>`;}).join('')}</div></section></div>`;focusDialog();}
function researchDialog(){if(!interactive())return;modal.innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="Research"><div class="dialog-head"><div><div class="eyebrow">Fleet research bureau</div><h2>A technological advantage</h2><p><span class="resource-inline">${count(game.economy[game.player].credits)} credits · ${count(game.economy[game.player].science)} research</span></p></div><button class="small close" data-action="close">Close</button></div><div class="tech-grid">${Object.entries(E.TECHS).map(([k,t])=>{const l=game.tech[game.player][k],c=E.researchCost(game,game.player,k),e=game.economy[game.player];return `<section class="tech-card"><span class="label">Level ${l} / 3 · Fleetwide</span><h3>${t.name}</h3><p>${t.desc}</p><div class="tech-levels">${[1,2,3].map(n=>`<i class="${n<=l?'unlocked':''}"></i>`).join('')}</div><button data-research="${k}" ${l>=3||e.credits<c.credits||e.science<c.science?'disabled':''}>${l===3?'Research complete':`Research level ${l+1} · ${c.credits} cr + ${c.science} research`}</button></section>`;}).join('')}</div></section></div>`;focusDialog();}
function admiralDialog(){if(!interactive())return;const u=selectedUnit(),eligible=u?.side===game.player&&!u.admiral;modal.innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="Fleet admirals"><div class="dialog-head"><div><div class="eyebrow">High command · ${E.FACTIONS[game.player].name}</div><h2>Fleet admirals</h2><p>${eligible?'Assign an officer to '+E.TYPES[u.type].name+' ×'+u.stack:'Select one of your fleets without an admiral to assign a commander.'}</p></div><button class="small close" data-action="close">Close</button></div><div class="info-strip">Admirals remain with their fleet. Any admiral can command any hull; branch bonuses apply only to their specialty. A lost officer becomes available to commission again.</div><div class="admiral-grid">${Object.entries(E.ADMIRALS).filter(([k,a])=>a.side===game.player).map(([k,a])=>{const assigned=game.units.find(v=>v.hp>0&&v.admiral===k);return `<section class="officer">${ART.portrait(k,"officer-portrait")}<span class="stars">${'★'.repeat(a.stars)}</span><h3>${a.name}</h3><span class="label">${a.role} · ${a.skill}</span><p>${a.desc}</p><button data-admiral="${k}" ${assigned||!eligible||game.economy[game.player].credits<a.cost?'disabled':''}>${assigned?'Assigned to '+E.TYPES[assigned.type].short:eligible?'Assign · '+a.cost+' credits':a.cost+' credits · Select an unassigned fleet'}</button></section>`;}).join('')}</div></section></div>`;focusDialog();}
function archiveDialog(branch='Escort'){modal.innerHTML=`<div class="overlay"><section class="dialog wide" role="dialog" aria-modal="true" aria-label="Unit archive"><div class="dialog-head"><div><div class="eyebrow">Order of battle</div><h2>The fleet arsenal</h2><p>WC4 branches translated into your Galactic Heroes unit classes. Values shown for one stack.</p></div><button class="small close" data-action="close">Close</button></div><div class="tabs">${['Escort','Battle Line','Artillery'].map(b=>`<button data-archive-branch="${b}" class="${b===branch?'active':''}">${b}</button>`).join('')}</div><div class="cards">${Object.entries(E.TYPES).filter(([k,t])=>t.branch===branch).map(([k,t])=>`<article class="unit-card">${ART.ship(k,"catalog-ship")}<span class="unit-code">${t.code} · Tier ${t.tier}</span><h3>${t.name}</h3><span class="label">${t.wc} equivalent</span><p style="margin-top:12px">${t.desc}</p><div class="unit-spec"><span>HP ${t.hp}</span><span>ATK ${t.attack}</span><span>ARM ${t.armor}</span><span>MOV ${t.move}</span><span>RNG ${t.min}–${t.max}</span></div><div class="cost">${t.cost} credits · ${t.industry} industry</div></article>`).join('')}</div></section></div>`;focusDialog();}
function helpDialog(){modal.innerHTML=`<div class="overlay"><section class="dialog" role="dialog" aria-modal="true" aria-label="Field manual"><div class="dialog-head"><div><div class="eyebrow">Field manual</div><h2>War on a hex grid</h2></div><button class="small close" data-action="help-close">Close</button></div><div class="help-grid"><div><b>Movement & firing</b><p>Every fleet can move once, then attack once per turn. Attacking spends its movement too. Select a fleet and click a blue hex to move. Click a red target to inspect expected damage, then press Fire or F.</p></div><div><b>Capture stations</b><p>Destroy station defenses and remove its garrison, then move an Escort or Battle Line fleet onto the hex. Artillery cannot capture. Friendly stations produce resources and repair garrisons by 8% HP each turn.</p></div><div><b>Artillery & counter-fire</b><p>Beam frigates and siege hulls fire 1–2 hexes. Arsenal ships splash adjacent enemies for 45% damage. Spinal batteries fire 2–3 hexes and move only 1. All artillery suppresses counter-fire. Other hulls retaliate only when the attacker is in range.</p></div><div><b>Stacking & breakthroughs</b><p>Build 1–3-stack fleets. Each extra stack adds 70% HP and 45% attack. Add stacks near friendly stations. Battle Line kills refresh movement and fire once per turn; Mittermeyer and Attenborough allow two refreshes.</p></div><div><b>Admirals & morale</b><p>Attach officers to any fleet; specialty bonuses use their listed branch. High morale grants +25% damage; low −25%, diminished −50%. Confused fleets cannot act or retaliate. Two adjacent enemies lower morale; three diminish it. Yang’s Confusion reduces nearby enemy morale by 2.</p></div><div><b>Terrain & supply</b><p>Nebulae cost 2 movement and cause 2.5% attrition each turn. Asteroids cost 2 movement and reduce damage by 15%. Yang ignores terrain movement costs. Gravity rifts are impassable. Capture the three crossings to invade the other side.</p></div><div><b>Shipyards & research</b><p>Each station builds one fleet per turn. New units act next turn. Upgrade yards through tier 3 to unlock heavy hulls. Research applies immediately to your entire fleet. Elite batteries cannot stack.</p></div><div><b>Your objectives</b><p>Conquest: hold both capitals, or hold more stations at the 50-turn armistice. Iserlohn: capture the fortress within 18 turns. Difficulties change starting resources and enemy income, not the combat rules.</p></div></div><div class="info-strip">Controls: N cycles ready fleets · F fires · Escape cancels a target or closes a menu · Arrow keys move the hex cursor and Enter selects · Drag or WASD pans · Scroll / + / − zooms · 0 fits the map.</div><p style="font-size:12px">Unofficial fan game. Original code and alternate-history scenarios, using the requested ship-class mappings. Gameplay draws on <a href="https://apps.apple.com/sg/app/world-conqueror-4/id1258468290" target="_blank" rel="noopener noreferrer">EasyTech’s World Conqueror 4</a>; <a href="https://world-conqueror-4.fandom.com/wiki/Units" target="_blank" rel="noopener noreferrer">unit reference</a>. Numbers and some abilities are adapted for this game.</p></section></div>`;focusDialog();}
function menuDialog(){modal.innerHTML=`<div class="overlay"><section class="dialog narrow" role="dialog" aria-modal="true" aria-label="Game menu"><div class="eyebrow">Command headquarters</div><h2>Your orders, Admiral.</h2><p>Your current operation is saved automatically in this browser. The previous real-time game’s save is kept separately.</p><div class="dialog-footer"><div><button class="primary" data-action="close">Resume</button><button data-action="new">New operation</button><button data-action="help">Field manual</button></div></div></section></div>`;focusDialog();}
function hexCenter(p){return{x:SQ*R*(p.c+.5*(p.r&1))+R,y:R*1.5*p.r+R};}
function computeView(){const rect=canvas.getBoundingClientRect();mapSize={w:rect.width,h:rect.height};const width=SQ*R*(game.cols+.5)+R,height=R*1.5*(game.rows-1)+2*R;const compact=rect.width<700;const top=compact?120:130,bottom=compact?205:175;fitScale=Math.min((rect.width-70)/width,(rect.height-top-bottom)/height);fitScale=Math.max(.22,fitScale);const scale=fitScale*zoom;offset={x:(rect.width-width*scale)/2+pan.x,y:top+(rect.height-top-bottom-height*scale)/2+pan.y};return scale;}
function centerOn(p){const scale=computeView(),c=hexCenter(p);pan.x+=mapSize.w/2-(c.x*scale+offset.x);pan.y+=mapSize.h/2-(c.y*scale+offset.y);}
function hitHex(clientX,clientY){const rect=canvas.getBoundingClientRect(),scale=computeView(),x=(clientX-rect.left-offset.x)/scale,y=(clientY-rect.top-offset.y)/scale;let nearest=null,best=R;for(const t of game.tiles){const p=hexCenter(t),d=Math.hypot(p.x-x,p.y-y);if(d<best){best=d;nearest=t;}}return nearest;}
function changeZoom(factor,anchor){const oldScale=computeView(),oldOffset={...offset};zoom=E.clamp(zoom*factor,.7,3.2);const newScale=computeView();if(anchor){const wx=(anchor.x-oldOffset.x)/oldScale,wy=(anchor.y-oldOffset.y)/oldScale;pan.x+=anchor.x-(wx*newScale+offset.x);pan.y+=anchor.y-(wy*newScale+offset.y);}}
function activateHex(p){if(!p)return;const u=selectedUnit(),hit=E.unitAt(game,p),station=E.stationAt(game,p);if(u?.side===game.player&&interactive()){
 if(targetCache.has(E.key(p))){target={c:p.c,r:p.r};updateSelection();return;}
 if(readyCache.has(E.key(p))){const result=E.move(game,u.id,p.c,p.r);if(result.ok){effects.push({kind:'move',unitId:u.id,from:result.from,to:result.to,color:E.FACTIONS[u.side].color,life:.45,max:.45});target=null;refreshAndSave();if(result.captured)toast(`${result.captured} captured. +40 credits.`);return;}}
 }
 target=null;if(hit)selectUnit(hit.id);else if(station)selectStation(station.id);else{selection={kind:'tile',c:p.c,r:p.r};updateSelection();}}
function attachMap(){canvas.onpointerdown=e=>{if(e.button!==0&&e.pointerType!=='touch')return;canvas.focus({preventScroll:true});pointer={x:e.clientX,y:e.clientY,pan:{...pan},dragged:false,id:e.pointerId};canvas.setPointerCapture(e.pointerId);};canvas.onpointermove=e=>{if(pointer){const dx=e.clientX-pointer.x,dy=e.clientY-pointer.y;if(Math.hypot(dx,dy)>5)pointer.dragged=true;if(pointer.dragged){pan.x=pointer.pan.x+dx;pan.y=pointer.pan.y+dy;canvas.style.cursor='grabbing';}}hover=hitHex(e.clientX,e.clientY);if(hover&&!pointer?.dragged){canvas.style.cursor=readyCache.has(E.key(hover))||targetCache.has(E.key(hover))?'pointer':'default';const u=E.unitAt(game,hover),s=E.stationAt(game,hover);$('map-caption').textContent=`Hex ${hover.c}, ${hover.r} · ${u?E.TYPES[u.type].short+' · ':''}${s?s.name+' · ':''}${hover.terrain==='space'?'Deep space':hover.terrain==='rift'?'Impassable rift':hover.terrain==='nebula'?'Nebula · cost 2 · attrition':'Asteroids · cost 2 · −15% damage'}`;}};canvas.onpointerup=e=>{if(pointer&&!pointer.dragged)activateHex(hitHex(e.clientX,e.clientY));pointer=null;canvas.style.cursor='default';};canvas.onpointercancel=()=>pointer=null;canvas.onpointerleave=()=>{if(!pointer)hover=null;};canvas.onwheel=e=>{e.preventDefault();const rect=canvas.getBoundingClientRect();changeZoom(e.deltaY<0?1.1:1/1.1,{x:e.clientX-rect.left,y:e.clientY-rect.top});};canvas.oncontextmenu=e=>e.preventDefault();}
function addCombatEffects(result,side){effects.push({kind:'beam',from:result.from,to:result.to,color:E.FACTIONS[side].color,life:.75,max:.75});if(result.shieldDamage)effects.push({kind:'text',to:result.to,text:'−'+result.shieldDamage+' DEF',color:'#e3b46f',life:1.6,max:1.6,dy:17});for(const h of result.hit||[])effects.push({kind:'text',to:h,text:'−'+h.damage+(result.crit?' CRIT':''),color:'#ffa397',life:1.5,max:1.5,dy:0});if(result.counter)effects.push({kind:'text',to:result.from,text:'−'+result.counter,color:'#ffa397',life:1.5,max:1.5,dy:0});}
const stars=Array.from({length:160},(_,i)=>({x:((Math.sin(i*127.1+1)*43758.5453)%1+1)%1,y:((Math.sin(i*311.7+7)*19731.234)%1+1)%1,a:.1+(i%7)*.05}));
function hexPath(x,y,r){ctx.beginPath();for(let i=0;i<6;i++){const a=Math.PI/180*(60*i-30),px=x+r*Math.cos(a),py=y+r*Math.sin(a);i?ctx.lineTo(px,py):ctx.moveTo(px,py);}ctx.closePath();}
function drawLine(x,y,tx,ty,color,width=1,dash=[]){ctx.beginPath();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.moveTo(x,y);ctx.lineTo(tx,ty);ctx.stroke();ctx.setLineDash([]);}
/* Battlefield renderer is supplied below. */
function frame(time){const dt=Math.min(.05,(time-lastTime)/1000||.016);lastTime=time;draw(time,dt);requestAnimationFrame(frame);}
let helpBack='game';
document.addEventListener('change',e=>{const id=e.target.id;if(id==='mode-select')setup.mode=e.target.value;if(id==='difficulty-select')setup.difficulty=e.target.value;if(id==='fleet-select'&&e.target.value)selectUnit(+e.target.value,true);if(id==='station-select'&&e.target.value)selectStation(+e.target.value,true);if(id==='stack-select'){shop.stack=+e.target.value;openShop(shop.station);}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.faction){setup.side=d.faction;setup.mode=$('mode-select').value;setup.difficulty=$('difficulty-select').value;startMenu();return;}if(d.station){selectStation(+d.station);return;}if(d.shop){openShop(+d.shop);return;}if(d.branch){openShop(shop.station,d.branch);return;}if(d.archiveBranch){archiveDialog(d.archiveBranch);return;}
 if(d.recruit){const r=E.recruit(game,shop.station,d.recruit,E.TYPES[d.recruit].elite?1:shop.stack);if(r.ok){selection={kind:'unit',id:r.unit.id};closeModal();refreshAndSave();toast('Fleet commissioned. It will be ready next turn.');}else toast(r.reason);return;}
 if(d.research){const r=E.research(game,d.research);if(r.ok){render();save();researchDialog();}else toast(r.reason);return;}
 if(d.admiral){const u=selectedUnit(),r=u?E.assign(game,u.id,d.admiral):{ok:false,reason:'Select a fleet first.'};if(r.ok){closeModal();refreshAndSave();toast(`${E.ADMIRALS[d.admiral].short} assumes command.`);}else toast(r.reason);return;}
 switch(d.action){case'details':detailOpen=!detailOpen;updateSelection();break;case'start':setup.mode=$('mode-select').value;setup.difficulty=$('difficulty-select').value;newGame();break;case'continue':{const s=getSave();if(s){aiToken++;game=s;selection=null;target=null;zoom=1;pan={x:0,y:0};closeModal();render();if(game.over)resultDialog();}break;}case'new':startMenu();break;case'close':closeModal();break;case'help':helpBack=$('mode-select')?'start':'game';helpDialog();break;case'help-close':if(helpBack==='start')startMenu();else closeModal();break;case'menu':menuDialog();break;case'next':nextFleet();break;case'fire':executeFire();break;case'cancel-target':target=null;updateSelection();break;case'research':researchDialog();break;case'admirals':case'assign':admiralDialog();break;case'archive':archiveDialog();break;case'end':endTurn();break;case'end-confirm':endTurn(true);break;case'confuse':{const u=selectedUnit();if(u)doAction(()=>E.confuse(game,u.id));break;}case'reinforce':{const u=selectedUnit();if(u)doAction(()=>E.reinforce(game,u.id));break;}case'repair':{const u=selectedUnit();if(u)doAction(()=>E.repair(game,u.id));break;}case'upgrade':{const s=selectedStation();if(s)doAction(()=>E.upgrade(game,s.id));break;}case'wait':{const u=selectedUnit();if(u&&u.side===game.player&&interactive()){u.moved=u.attacked=true;refreshAndSave();nextFleet();}break;}case'zoom-in':changeZoom(1.2);break;case'zoom-out':changeZoom(1/1.2);break;case'fit':zoom=1;pan={x:0,y:0};break;}
});
document.addEventListener('keydown',e=>{if(modal.children.length){if(e.key==='Tab'){const list=[...modal.querySelectorAll('button:not(:disabled),select,a[href]')],first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='Escape'&&!$('mode-select'))closeModal();return;}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if(k==='n'){e.preventDefault();nextFleet();}if(k==='f'){e.preventDefault();executeFire();}if(k==='escape'){target=null;selection=null;updateSelection();}if(k==='+'||k==='=')changeZoom(1.2);if(k==='-')changeZoom(1/1.2);if(k==='0'){zoom=1;pan={x:0,y:0};}if(['w','a','s','d'].includes(k)){e.preventDefault();pan.x+=k==='a'?70:k==='d'?-70:0;pan.y+=k==='w'?70:k==='s'?-70:0;}if(e.key.startsWith('Arrow')){e.preventDefault();const p=hover||selectedUnit()||selectedStation()||{c:Math.floor(game.cols/2),r:Math.floor(game.rows/2)};hover=E.tile(game,E.clamp(p.c+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0),0,game.cols-1),E.clamp(p.r+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0),0,game.rows-1));}if(k==='enter'&&document.activeElement===canvas){e.preventDefault();activateHex(hover);}});
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const defs=[{name:'read_hex_campaign',description:'Read current hex campaign resources, fleets, stations, and whose turn it is.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({turn:game.turn,phase:game.phase,player:game.player,resources:game.economy[game.player],stations:game.stations,units:game.units.filter(u=>u.hp>0),result:game.over})},{name:'select_hex_fleet',description:'Select a living fleet on the map. Does not move or attack.',inputSchema:{type:'object',properties:{unitId:{type:'integer'}},required:['unitId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(modal.children.length)throw new Error('Close the open dialog first.');if(!Number.isInteger(input.unitId)||!game.units.some(u=>u.id===input.unitId&&u.hp>0))throw new Error('Invalid unit ID.');selectUnit(input.unitId,true);return{selectedUnitId:input.unitId};}}];for(const t of defs){try{Promise.resolve(context.registerTool(t)).catch(()=>{});}catch(e){}}}
/* INITIALIZE_GAME */
function dockHTML(){
 const u=selectedUnit(),s=selectedStation();
 if(u){const t=E.TYPES[u.type],a=E.ADMIRALS[u.admiral],ours=u.side===game.player,pr=target?E.preview(game,u.id,target.c,target.r):null;return `<div class="dock-visual">${ART.ship(u.type)}${a?ART.portrait(u.admiral,'dock-portrait'):''}<span class="faction-flag ${u.side}">${u.side==='empire'?'I':'A'}</span></div><div class="dock-unit"><span class="label">${a?a.short+' · ':''}${t.branch} · ×${u.stack}</span><strong>${a&&u.type==='flagship'?a.hull:t.short}</strong><div class="dock-health"><div class="bar"><i style="width:${u.hp/E.maxHP(u)*100}%"></i></div><span>${Math.ceil(u.hp)} / ${E.maxHP(u)}</span></div><p>MOV ${E.movement(game,u)} &nbsp; RNG ${t.min}–${t.max} &nbsp; ${u.attacked?'Orders complete':moraleName(u.morale)}</p></div><div class="dock-actions">${pr?`<span class="firing-estimate">~${pr.unit||pr.shield} damage · ${pr.counterAllowed?pr.counter+' counter-fire':'No counter-fire'}</span><button class="fire-button" data-action="fire" ${!interactive()||u.attacked||u.morale<=-3?'disabled':''}>Fire <span class="kbd">F</span></button><button class="small ghost" data-action="cancel-target">Cancel</button>`:`<button class="small" data-action="details">${ours?'Orders & upgrades':'Fleet details'}</button>${ours&&!u.admiral?'<button class="small" data-action="assign">Assign admiral</button>':''}${ours&&u.admiral==='yang'?`<button class="small" data-action="confuse" ${!interactive()||u.confusionCD>0?'disabled':''}>Confusion${u.confusionCD?' · '+u.confusionCD:''}</button>`:''}${ours?`<button class="small ghost" data-action="wait" ${!interactive()||u.attacked?'disabled':''}>Hold position</button>`:''}`}</div>`;}
 if(s){const ours=s.owner===game.player;return `<div class="dock-visual">${ART.ship(s.capital?'capital':s.fort?'fortress':'station')}<span class="faction-flag ${s.owner}">${s.owner==='empire'?'I':s.owner==='alliance'?'A':'N'}</span></div><div class="dock-unit"><span class="label">${s.fort?'Fortress':s.capital?'Capital':'Sector hub'} · Shipyard ${s.tier}</span><strong>${s.name}</strong><div class="dock-health"><div class="bar"><i style="width:${s.shield/s.maxShield*100}%"></i></div><span>${Math.ceil(s.shield)} / ${s.maxShield} DEF</span></div><p>Income +${s.income} &nbsp; Industry +${s.industry}</p></div><div class="dock-actions">${ours?`<button class="primary" data-shop="${s.id}" ${!interactive()?'disabled':''}>Shipyard</button>`:''}<button class="small" data-action="details">Station details</button></div>`;}
 return `<div class="dock-idle"><span class="label">Fleet command</span><strong>Select a fleet or station</strong><p>Click a ship to move and attack. Click a station to build.</p></div><div class="dock-actions"><button class="small" data-action="next">Select a ready fleet</button><button class="small ghost" data-action="details">Fleet directory</button></div>`;
}
function selectionBrackets(x,y,r,scale){ctx.strokeStyle='#f4df64';ctx.shadowColor='#f7d64f';ctx.shadowBlur=5;ctx.lineWidth=3/scale;for(const sx of [-1,1])for(const sy of [-1,1]){ctx.beginPath();ctx.moveTo(x+sx*(r-10),y+sy*r);ctx.lineTo(x+sx*r,y+sy*r);ctx.lineTo(x+sx*r,y+sy*(r-10));ctx.stroke();}ctx.shadowBlur=0;}
function mapBadge(x,y,side,scale){const radius=Math.max(7,7/scale);ctx.save();ctx.translate(x,y);ctx.beginPath();ctx.arc(0,0,radius,0,Math.PI*2);ctx.fillStyle=side==='empire'?'#922f32':side==='alliance'?'#2e778a':'#665774';ctx.fill();ctx.strokeStyle='#eee6c5';ctx.lineWidth=1.4/scale;ctx.stroke();ctx.font=`bold ${Math.max(9,8/scale)}px Georgia`;ctx.textAlign='center';ctx.fillStyle='#fff8df';ctx.fillText(side==='empire'?'I':side==='alliance'?'A':'N',0,3/scale);ctx.restore();}
function outlinedText(text,x,y,size,color,scale,font='Trebuchet MS'){ctx.font=`${Math.max(size,size/scale)}px '${font}'`;ctx.textAlign='center';ctx.lineWidth=3/scale;ctx.strokeStyle='#06121fdd';ctx.strokeText(text,x,y);ctx.fillStyle=color;ctx.fillText(text,x,y);}
function animatedPosition(u){const p=hexCenter(u),fx=effects.find(e=>e.kind==='move'&&e.unitId===u.id&&e.life>0);if(!fx)return p;const start=hexCenter(fx.from),t=1-fx.life/fx.max,ease=1-Math.pow(1-t,3);return{x:start.x+(p.x-start.x)*ease,y:start.y+(p.y-start.y)*ease};}
function draw(time,dt){
 if(!canvas||!ctx)return;const scale=computeView(),{w,h}=mapSize,dpr=Math.min(devicePixelRatio||1,2);
 if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}
 ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#102b3e';ctx.fillRect(0,0,w,h);
 const wash=ctx.createRadialGradient(w*.48,h*.5,50,w*.5,h*.5,Math.max(w,h)*.75);wash.addColorStop(0,'#244658');wash.addColorStop(.6,'#142f43');wash.addColorStop(1,'#071423');ctx.fillStyle=wash;ctx.fillRect(0,0,w,h);
 for(let i=0;i<7;i++){ctx.globalAlpha=.11;ART.draw(ctx,'terrain',4+i%4,w*((i*.317+.12)%1),h*((i*.463+.21)%1),w*.6,h*.65);}ctx.globalAlpha=1;
 for(const star of stars){ctx.fillStyle=`rgba(211,229,229,${star.a*.75})`;ctx.fillRect(star.x*w,star.y*h,1.2,1.2);}
 ctx.save();ctx.translate(offset.x,offset.y);ctx.scale(scale,scale);ctx.lineWidth=.65/scale;
 for(const t of game.tiles){const p=hexCenter(t);hexPath(p.x,p.y,R);ctx.fillStyle=t.terrain==='rift'?'#07131e':t.owner==='empire'?'#a59a602c':t.owner==='alliance'?'#358b9c26':'#78829b0a';ctx.fill();ctx.strokeStyle='#b5c8cf13';ctx.stroke();}
 // Territorial borders remain visible when the tactical grid is subtle.
 for(const t of game.tiles){if(t.terrain==='rift')continue;const p=hexCenter(t);for(const n of E.adjacent(game,t)){if(n.owner===t.owner&&n.terrain!=='rift')continue;const q=hexCenter(n),angle=Math.atan2(q.y-p.y,q.x-p.x),i=Math.round(angle/(Math.PI/3)),a=(i*60-30)*Math.PI/180,b=(i*60+30)*Math.PI/180;drawLine(p.x+R*Math.cos(a),p.y+R*Math.sin(a),p.x+R*Math.cos(b),p.y+R*Math.sin(b),n.terrain==='rift'?'#93a9b35a':t.owner==='empire'?'#d2ba7a8f':'#5bb9d899',1.4/scale);}}
 // Painted terrain props are actual raster assets, kept separate from hit regions.
 for(const t of game.tiles){const p=hexCenter(t);if(t.terrain==='nebula'){ctx.globalAlpha=.65;ART.draw(ctx,'terrain',4+(t.c+t.r)%4,p.x,p.y,R*2.6,R*2.6);ctx.globalAlpha=1;}else if(t.terrain==='asteroid'){ART.draw(ctx,'terrain',(t.c+t.r)%4,p.x,p.y-3,R*1.9,R*1.9);}else if(t.terrain==='rift'){ctx.globalAlpha=.36;ART.draw(ctx,'terrain',13,p.x,p.y,R*1.8,R*1.8);ctx.globalAlpha=1;outlinedText('×',p.x,p.y+3,11,'#93a6b66b',scale);}
 if(readyCache.has(E.key(t))){hexPath(p.x,p.y,R-1);ctx.fillStyle='#afd7e215';ctx.fill();ctx.strokeStyle='#81b7c787';ctx.lineWidth=1.1/scale;ctx.stroke();if(!E.unitAt(game,t)&&!E.stationAt(game,t)){ctx.beginPath();ctx.arc(p.x,p.y,2.2/scale,0,Math.PI*2);ctx.fillStyle='#bddce5a0';ctx.fill();}}
 if(targetCache.has(E.key(t))){hexPath(p.x,p.y,R-1);ctx.fillStyle='#b4584320';ctx.fill();ctx.strokeStyle='#e9957677';ctx.stroke();}}
 for(const s of game.stations){const p=hexCenter(s),col=E.FACTIONS[s.owner].color,garrison=E.unitAt(game,s),index=s.capital?15:s.fort?14:13;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=garrison?.75:1;ctx.shadowColor='#0008';ctx.shadowBlur=7;ctx.shadowOffsetY=5;ART.draw(ctx,'fleet',index,0,s.fort?-8:-4,s.capital?R*2.8:s.fort?R*2.45:R*2.2,s.capital?R*2.8:s.fort?R*2.45:R*2.2);ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.globalAlpha=1;if(selection?.kind==='station'&&selection.id===s.id)selectionBrackets(0,0,31,scale);ctx.fillStyle='#071623';ctx.fillRect(-20,27,40,4);ctx.fillStyle='#bcb778';ctx.fillRect(-20,27,40*s.shield/s.maxShield,4);outlinedText(s.name,0,garrison?49:43,11,'#e8e7cc',scale);if(!garrison){mapBadge(-25,20,s.owner,scale);for(let i=0;i<s.tier;i++){ctx.fillStyle='#d8c581';ctx.fillRect(25,10-i*5,3,3);}}ctx.restore();}
 // Objects are drawn back to front for a miniature battlefield impression.
 for(const u of game.units.filter(u=>u.hp>0).sort((a,b)=>a.r-b.r||a.c-b.c)){const p=animatedPosition(u),t=E.TYPES[u.type],col=E.FACTIONS[u.side].color,sel=selection?.kind==='unit'&&selection.id===u.id,spent=u.moved&&u.attacked,index=ART.frames[u.type];ctx.save();ctx.translate(p.x,p.y);if(sel)selectionBrackets(0,0,34,scale);ctx.globalAlpha=spent?.66:1;
 // Extra hull silhouettes visualize stacks without hiding the readable front hull.
 const size=t.elite?R*2.7:u.type==='flagship'?R*2.6:t.branch==='Battle Line'?R*2.35:R*2.2;
 ctx.shadowColor='#000a';ctx.shadowBlur=5;ctx.shadowOffsetY=4;for(let i=Math.min(u.stack-1,2);i>=0;i--)ART.draw(ctx,'fleet',index,(i?i*7:0)-2,-8-i*8,size*(i?.88:1),size*(i?.88:1),u.side==='alliance');ctx.shadowBlur=0;ctx.shadowOffsetY=0;ctx.globalAlpha=1;
 if(!ART.ready.fleet){outlinedText(t.code,0,3,13,col,scale);}
 if(u.admiral){const img=ART.images.portraits;if(ART.ready.portraits&&img){const ind=ART.officers[u.admiral],rw=Math.max(20,20/scale),rh=rw*1.25,[sx,sy,sw,sh]=ART.rect('portraits',ind);ctx.save();ctx.beginPath();ctx.rect(-37,-40,rw,rh);ctx.clip();ctx.drawImage(img,sx,sy,sw,sh,-37,-40,rw,rh);ctx.restore();ctx.strokeStyle='#d9c27a';ctx.lineWidth=1/scale;ctx.strokeRect(-37,-40,rw,rh);}else{outlinedText('★',-25,-30,12,'#e9c366',scale);}if(sel||scale>.8)outlinedText(E.ADMIRALS[u.admiral].short,0,-46,10,'#f7e5ad',scale);}
 ctx.fillStyle='#061019';ctx.fillRect(-17,23,43,5);ctx.fillStyle=u.hp/E.maxHP(u)<.3?'#e07951':u.hp/E.maxHP(u)<.6?'#c3ac51':'#90bd55';ctx.fillRect(-16,24,41*u.hp/E.maxHP(u),3);mapBadge(-24,25,u.side,scale);for(let i=0;i<u.stack;i++){ctx.fillStyle='#e4d998';ctx.fillRect(-10+i*7,31,5,3);}if(!u.attacked&&u.side===game.player){ctx.beginPath();ctx.arc(30,22,2.5/scale,0,Math.PI*2);ctx.fillStyle='#e9e09b';ctx.fill();}if(u.morale<0)outlinedText(u.morale===-3?'!':'↓',30,-18,13,'#ffb78c',scale);ctx.restore();}
 if(hover&&!target){const p=hexCenter(hover);hexPath(p.x,p.y,R-1);ctx.strokeStyle='#dcebe769';ctx.lineWidth=1.2/scale;ctx.stroke();}
 if(target){const p=hexCenter(target),u=selectedUnit();ctx.save();ctx.translate(p.x,p.y);ctx.strokeStyle='#ed3930';ctx.lineWidth=2.8/scale;ctx.beginPath();ctx.ellipse(0,0,36,23,0,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.ellipse(0,0,27,16,0,0,Math.PI*2);ctx.stroke();for(const a of [0,Math.PI/2,Math.PI,Math.PI*1.5])drawLine(Math.cos(a)*19,Math.sin(a)*19,Math.cos(a)*42,Math.sin(a)*30,'#ff493b',2.6/scale);ctx.restore();if(u){const a=hexCenter(u);drawLine(a.x,a.y,p.x,p.y,'#eaa94d88',1.1/scale,[5,7]);}}
 for(const e of effects){e.life-=dt;const a=e.from?hexCenter(e.from):null,b=hexCenter(e.to);ctx.globalAlpha=Math.max(0,e.life/e.max);if(e.kind==='beam'){drawLine(a.x,a.y,b.x,b.y,e.color,4/scale);drawLine(a.x,a.y,b.x,b.y,'#fff6dd',1.6/scale);ART.draw(ctx,'terrain',15,b.x,b.y,95*(1.15-e.life/e.max*.45),95*(1.15-e.life/e.max*.45));}else if(e.kind==='move'){drawLine(a.x,a.y,b.x,b.y,e.color,2/scale,[7,6]);}else if(e.kind==='text'){outlinedText(e.text,b.x,b.y-28-(1-e.life/e.max)*28-(e.dy||0),14,e.color,scale,'Courier New');}ctx.globalAlpha=1;}effects=effects.filter(e=>e.life>0);ctx.restore();
}
